void hg_queue_drag(int x0, int y0, int x1, int y1, int steps)
{
    int i;
    int n = steps;

    if(n < 2) n = 2;
    hg_push_step(x0, y0, 2);
    for(i = 1; i <= n; i++) {
        int x = x0 + (x1 - x0) * i / n;
        int y = y0 + (y1 - y0) * i / n;
        hg_push_step(x, y, 1);
    }
    hg_push_step(x1, y1, 0);
}

