static time_t runtime_report_mtime(void)
{
  struct stat st;
  char path[128];

  snprintf(path, sizeof(path), "%s/runtime-report.md",
           CONFIG_VG_HMI_REPORT_DIR);
  if(stat(path, &st) != 0) {
    return 0;
  }

  return st.st_mtime;
}

if(do_report_read && allow_gen) {
  time_t baseline = runtime_report_mtime();
  bool ok = board_request_daily_report();

  pthread_mutex_lock(&g_file_worker_lock);
  if(ok) {
    g_report_gen_mtime = baseline;
    g_report_snap.status = VG_UI_REPORT_GENERATING;
    g_report_gen_start_ms = vg_live_now_ms();
    g_report_snap.elapsed_s = 0;
    g_report_snap.err = 0;
    g_report_snap.version++;
    last_gen_poll_ms = g_report_gen_start_ms;
    printf("vghmi: report poke mtime=%ld\n", (long)baseline);
  }
  else {
    g_report_snap.status = VG_UI_REPORT_EMPTY;
    g_report_snap.err = -ENOSYS;
    g_report_snap.version++;
  }
  pthread_mutex_unlock(&g_file_worker_lock);
}
else if(do_report_read || do_report_check_gen) {
  char body[1024];
  char path[128];
  int rc = -ENOENT;
  bool take = !do_report_check_gen;

  if(do_report_check_gen) {
    time_t mt = runtime_report_mtime();

    take = (mt != 0 && mt != g_report_gen_mtime);
  }

  if(take) {
    if(do_report_check_gen) {
      char runtime_path[128];

