#include <unistd.h>

input.command:
powershell.exe -ExecutionPolicy Bypass -Command '
$ErrorActionPreference = "Stop"
$port = New-Object System.IO.Ports.SerialPort
$port.PortName = "COM3"
$port.BaudRate = 115200
$port.ReadTimeout = 8000
$port.DtrEnable = $true
$port.NewLine = "`r"
$port.Open()
Start-Sleep -Seconds 2
while ($port.BytesToRead -gt 0) { [void]$port.ReadExisting(); Start-Sleep -Milliseconds 40 }
function Send-Cmd($cmd, $wait=8) {
  $port.DiscardInBuffer()
  $port.Write($cmd + "`r")
  Start-Sleep -Milliseconds 350
  $buf = ""
  $deadline = (Get-Date).AddSeconds($wait)
  while ((Get-Date) -lt $deadline) {
    if ($port.BytesToRead -gt 0) { $buf += $port.ReadExisting() }
    if ($buf -match "nsh>") { break }
    Start-Sleep -Milliseconds 120
  }
  Write-Output ("=== " + $cmd + " ===")
  Write-Output $buf
  return $buf
}
Send-Cmd "echo nsh-ok" 5 | Out-Null
$r1 = Send-Cmd "cat /data/velaguard/reports/runtime-report.md" 8
$r2 = Send-Cmd "head -n 8 /data/agent/HEARTBEAT.md" 6
$r3 = Send-Cmd "vgruntime dump" 8
$port.Close()
Write-Output "---- CHECKS ----"
if ($r1 -match "通信质量") { Write-Output "[PASS] report has 通信质量" } else { Write-Output "[FAIL] report missing 通信质量" }
if ($r1 -match "点位在线") { Write-Output "[PASS] report has 点位在线" } else { Write-Output "[FAIL] report missing 点位在线" }
if ($r1 -match "异常时间线") { Write-Output "[PASS] report has 异常时间线" } else { Write-Output "[FAIL] report missing 异常时间线" }
if ($r1 -match "vgruntime: slave=") { Write-Output "[FAIL] report still dump lines" } else { Write-Output "[PASS] report has no dump lines" }
if ($r2 -match "不要写 runtime-report") { Write-Output "[PASS] HEARTBEAT seed updated" } else { Write-Output "[WARN] HEARTBEAT seed not updated yet" }
if ($r3 -match "vgruntime: uptime_s=") { Write-Output "[PASS] vgruntime dump live" } else { Write-Output "[FAIL] vgruntime dump empty" }
'

input.new_string:
int main(int argc, char *argv[])
{
  vg_runtime_init();

  if (argc >= 2 && strcmp(argv[1], "dump") == 0)
    {
      vg_runtime_fprint_dump(stdout);
      return 0;
    }

  if (argc >= 2 && strcmp(argv[1], "report") == 0)
    {
      const char *path = "/data/velaguard/reports/runtime-report.md";
      int rc;

      if (argc >= 3 && argv[2][0] != '\0')
        {
          path = argv[2];
        }

      rc = vg_runtime_write_report(path);
      if (rc != 0)
        {
          printf("vgruntime: write %s failed (%d)\n", path, rc);
          return 1;
        }

      printf("vgruntime: wrote %s\n", path);
      vg_runtime_fprint_report(stdout);
      return 0;
    }

  printf("Usage: vgruntime dump | report [path]\n");
  return 1;
}

